// Wheel artwork from the reviewed landscape cockpit prototype.
export function cockpitWheel(id){
const ring=(color,trim,spokes)=>`<defs><linearGradient id="rim" x2=".7" y2="1"><stop stop-color="${trim}"/><stop offset=".23" stop-color="${color}"/><stop offset=".67" stop-color="#202527"/><stop offset="1" stop-color="${color}"/></linearGradient><linearGradient id="spoke" x2="0" y2="1"><stop stop-color="${trim}"/><stop offset=".5" stop-color="#7e8989"/><stop offset="1" stop-color="#303b40"/></linearGradient></defs><circle cx="75" cy="75" r="64" fill="none" stroke="#171c1d" stroke-width="19"/><circle cx="75" cy="75" r="64" fill="none" stroke="url(#rim)" stroke-width="14"/><circle cx="75" cy="75" r="55" fill="none" stroke="#afb4a8" stroke-opacity=".4" stroke-width="1"/><path d="${spokes}" fill="url(#spoke)" stroke="#182124" stroke-width="2"/><path d="M28 36Q75-1 122 36" fill="none" stroke="${trim}" stroke-opacity=".7" stroke-width="2"/><path class="wheel-centre-mark" d="M75 4v14" stroke="#d7b27c" stroke-width="4"/>`;
const wheels={
hatch:ring('#343433','#72716c','M21 53L64 64 83 64 128 53 129 69 89 84 84 129H66L62 84 21 69Z')+'<path d="M35 23Q75 2 115 23" stroke="#9f5043" stroke-width="3" fill="none"/><circle cx="75" cy="75" r="28" fill="#282c2b" stroke="#161c1d" stroke-width="3"/><circle cx="75" cy="75" r="23" fill="none" stroke="#666c64"/><path d="M12 65v21M138 65v21" stroke="#9f5043" stroke-width="2" stroke-dasharray="2 3"/>',
wedge:ring('#39484e','#97a5a7','M19 57L61 66H89L131 57 127 76 91 88 85 127H65L59 88 23 76Z')+'<path d="M50 61H100L103 88 91 102H59L47 88Z" fill="#596c74" stroke="#19272d" stroke-width="3"/><path d="M55 65H95" stroke="#bdc8c6" stroke-width="2"/><rect x="65" y="71" width="20" height="13" rx="2" fill="#273b43" stroke="#a8b5b1"/>',
nordic:'<defs><linearGradient id="leather" x2="0" y2="1"><stop stop-color="#e2d4b8"/><stop offset=".4" stop-color="#b7a98e"/><stop offset=".8" stop-color="#716b5f"/><stop offset="1" stop-color="#b9ad96"/></linearGradient><linearGradient id="nordic-metal" x2="0" y2="1"><stop stop-color="#c7d0c8"/><stop offset="1" stop-color="#687e82"/></linearGradient></defs><circle cx="75" cy="75" r="64" fill="none" stroke="#263237" stroke-width="19"/><circle cx="75" cy="75" r="64" fill="none" stroke="url(#leather)" stroke-width="13"/><circle cx="75" cy="75" r="55" fill="none" stroke="#eee2c7" stroke-opacity=".65"/><path d="M17 57L53 65H97L133 57 131 76 96 88 84 129H66L54 88 19 76Z" fill="url(#nordic-metal)" stroke="#293940" stroke-width="2"/><path d="M20 60L52 70H98L130 60M68 91L71 121M82 91L79 121" fill="none" stroke="#b59778" stroke-width="3"/><path d="M49 58Q75 50 101 58L105 83Q75 102 45 83Z" fill="#53646b" stroke="#26343b" stroke-width="3"/><path d="M55 62Q75 57 95 62" fill="none" stroke="#b1bdb4" stroke-width="2"/><path class="wheel-centre-mark" d="M75 4v14" stroke="#ad855e" stroke-width="4"/>'
};
return wheels[id] || wheels.hatch;
}

// Instrument art from the same reviewed landscape prototype.
export function cockpitInstrument(id){
const ticks=(cx,cy,r)=>Array.from({length:13},(_,i)=>{const a=(150+i*20)*Math.PI/180;return `<path d="M${cx+Math.cos(a)*r} ${cy+Math.sin(a)*r}l${Math.cos(a)*-5} ${Math.sin(a)*-5}"/>`;}).join('');
const art={
hatch:`<svg viewBox="0 0 300 76"><defs><linearGradient id="hatch-case" x2="0" y2="1"><stop stop-color="#34383b"/><stop offset=".35" stop-color="#171c20"/><stop offset="1" stop-color="#3f4142"/></linearGradient></defs><path d="M0 76L8 12Q9 2 22 2H278Q291 2 292 12L300 76Z" fill="url(#hatch-case)" stroke="#15191c" stroke-width="3"/><rect x="16" y="14" width="76" height="57" rx="4" fill="#20262a" stroke="#63686a"/><rect x="98" y="14" width="105" height="57" rx="4" fill="#20262a" stroke="#63686a"/><rect x="209" y="14" width="75" height="57" rx="4" fill="#20262a" stroke="#63686a"/><g fill="none" stroke="#d1d1c4" stroke-width="1.5">${ticks(54,54,26)}${ticks(247,54,26)}<path d="M112 27h74M112 32h74" stroke="#3d474a"/></g><path id="speed-needle" d="M54 54L33 62" stroke="#cb7240" stroke-width="3"/><path d="M247 54L226 61" stroke="#cb7240" stroke-width="3"/><circle cx="54" cy="54" r="4" fill="#7a7d76"/><circle cx="247" cy="54" r="4" fill="#7a7d76"/></svg>`,
wedge:`<svg viewBox="0 0 300 60"><path d="M2 58L14 3H286L298 58Z" fill="#39484f" stroke="#15232a" stroke-width="3"/><path d="M22 11H278L284 49H16Z" fill="#122c2a" stroke="#9baaa7" stroke-width="1.5"/><g fill="#8fae9b">${Array.from({length:11},(_,i)=>`<rect x="${29+i*7}" y="${38-i*1.5}" width="5" height="${7+i*1.5}"/>`).join('')}<path d="M206 18h5v26h-5zM216 18h5v26h-5zM226 18h5v26h-5zM236 18h5v26h-5z"/></g><path d="M251 18h5v26h-5zM261 18h5v26h-5z" fill="#a34d43"/><path d="M26 13H273" stroke="#638778" stroke-width="1"/></svg>`,
nordic:`<svg viewBox="0 0 280 76"><defs><linearGradient id="glass" x2="0" y2="1"><stop stop-color="#445965"/><stop offset=".5" stop-color="#1b2c36"/><stop offset="1" stop-color="#172a31"/></linearGradient></defs><path d="M3 74L11 13Q140-3 269 13L277 74Z" fill="url(#glass)" stroke="#1d2a30" stroke-width="3"/><path d="M14 70H266" stroke="#b39673" stroke-width="2"/><g class="nordic-gauge" fill="#1a3038" stroke="#baa184" stroke-width="2.5"><circle cx="78" cy="39" r="31"/><circle cx="202" cy="39" r="31"/></g><g fill="none" stroke="#c9d4ca" stroke-width="1.3">${ticks(78,39,26)}${ticks(202,39,26)}</g><path d="M202 40L184 50" stroke="#c48e63" stroke-width="2"/><circle cx="202" cy="40" r="3" fill="#cbb69c"/><path d="M128 52H152" stroke="#9ab1ad" stroke-width="2"/></svg>`,
scooter:`<svg viewBox="0 0 108 108"><defs><linearGradient id="scooter-rim" x2=".8" y2="1"><stop stop-color="#b6c6b3"/><stop offset=".35" stop-color="#315c4c"/><stop offset="1" stop-color="#183d32"/></linearGradient></defs><circle cx="54" cy="54" r="51" fill="url(#scooter-rim)" stroke="#193d32" stroke-width="3"/><circle cx="54" cy="54" r="43" fill="#e4d7b7" stroke="#778c76" stroke-width="2"/><g stroke="#536b5c" stroke-width="2">${ticks(54,54,35)}</g><path d="M54 58L29 75" stroke="#ae543c" stroke-width="3"/><circle cx="54" cy="58" r="4" fill="#2c5141"/></svg>`
};return art[id] || art.hatch;
}
